+};
+function walk(dir) {
+  for (const entry of readdirSync(dir, { withFileTypes: true })) {
+    const path = join(dir, entry.name);
+    if (entry.isDirectory()) walk(path);
+    else if (entry.name.endsWith(".css")) {
+      let text = readFileSync(path, "utf8");
+      const name = text.match(/@component ([\w.-]+)/u)?.[1];
+      if (!name || text.includes("@example -automatica11y")) continue;
+      const record = byName.get(name);
+      if (!record) throw new Error(`Missing ${name}`);
+      const parent = byName.get(name.split(".")[0]);
+      const examples = record.examples.length ? record.examples : parent.examples;
+      const selected = examples.find((example) => example.startsWith("-automatica11y")) ?? examples[0];
+      if (!selected) throw new Error(`No example for ${name}`);
+      let markup = overrides[name] ?? overrides[parent.name] ?? html(selected);
